create extension if not exists pgcrypto;
create type public.episode_status as enum ('draft','published','scheduled','archived');
create type public.person_role as enum ('host','guest','both');
create type public.social_post_status as enum ('draft','pending_approval','approved','publishing','published','failed','rejected');
create table public.episodes (id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,description text,artwork_url text,audio_url text,video_url text,spotify_url text,apple_podcasts_url text,source_guid text unique,source_url text,published_at timestamptz,duration_seconds integer check(duration_seconds is null or duration_seconds>=0),status public.episode_status not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.people (id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,role public.person_role not null default 'guest',bio text,image_url text,website_url text,instagram_url text,youtube_url text,spotify_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.episode_people (episode_id uuid not null references public.episodes(id) on delete cascade,person_id uuid not null references public.people(id) on delete cascade,appearance_role text not null default 'guest',sort_order integer not null default 0,primary key(episode_id,person_id));
create table public.media_assets (id uuid primary key default gen_random_uuid(),title text not null,description text,kind text not null check(kind in ('gallery','wallpaper')),file_url text not null,thumbnail_url text,alt_text text,width integer,height integer,is_public boolean not null default true,created_at timestamptz not null default now());
create table public.social_posts (id uuid primary key default gen_random_uuid(),episode_id uuid references public.episodes(id) on delete set null,platform text not null,caption text not null,media_url text,status public.social_post_status not null default 'pending_approval',requested_by text,approved_by text,approved_at timestamptz,published_url text,error_message text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.subscribers (id uuid primary key default gen_random_uuid(),email text not null unique,consented_at timestamptz not null default now(),confirmed_at timestamptz,unsubscribed_at timestamptz);
create table public.push_subscriptions (id uuid primary key default gen_random_uuid(),endpoint text not null unique,p256dh text not null,auth text not null,created_at timestamptz not null default now(),revoked_at timestamptz);
create table public.sync_runs (id uuid primary key default gen_random_uuid(),source text not null,status text not null,imported_count integer not null default 0,skipped_count integer not null default 0,error_summary text,started_at timestamptz not null default now());
create index episodes_status_published_idx on public.episodes(status,published_at desc); create index people_role_name_idx on public.people(role,name); create index media_assets_kind_created_idx on public.media_assets(kind,created_at desc); create index social_posts_status_created_idx on public.social_posts(status,created_at desc); create index sync_runs_started_idx on public.sync_runs(started_at desc);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
create trigger episodes_set_updated_at before update on public.episodes for each row execute function public.set_updated_at(); create trigger people_set_updated_at before update on public.people for each row execute function public.set_updated_at(); create trigger social_posts_set_updated_at before update on public.social_posts for each row execute function public.set_updated_at();
alter table public.episodes enable row level security; alter table public.people enable row level security; alter table public.episode_people enable row level security; alter table public.media_assets enable row level security; alter table public.social_posts enable row level security; alter table public.subscribers enable row level security; alter table public.push_subscriptions enable row level security; alter table public.sync_runs enable row level security;
create policy "Public can read published episodes" on public.episodes for select to anon,authenticated using(status='published'); create policy "Public can read people" on public.people for select to anon,authenticated using(true); create policy "Public can read episode people for published episodes" on public.episode_people for select to anon,authenticated using(exists(select 1 from public.episodes e where e.id=episode_id and e.status='published')); create policy "Public can read public media" on public.media_assets for select to anon,authenticated using(is_public=true);
insert into public.people(name,slug,role,bio) values('Kaspar','kaspar','host','Co-host of Guys Being Guys. Bio coming soon.'),('Mo','mo','host','Co-host of Guys Being Guys. Bio coming soon.') on conflict(slug) do nothing;
